extern char **environ;

/*
 * The name Claude Code runs under. CSM_CLAUDE_PROCESS replaces it, so the
 * tests can run while Claude Code is open (or pretend it is).
 */
#define CLAUDE_PROCESS "claude"

/* The project path in both variants: logical first, physical when it differs. */
struct pairs {
	struct path_pair p[2];
	size_t count;
};

struct entry_move {
	char *from, *to;
};

/* What a session directory move does: entries to rename, directories merged. */
struct moves {
	struct entry_move *items;
	size_t count, cap;
	char **dirs;
	size_t dir_count, dir_cap;
};

struct session_dir {
	char *name;
	char *path;
	char *new_cwd;
};

static char *dup_or_null(const char *s)
{
	return s != NULL ? xstrdup(s) : NULL;
}

static void note(struct move_ctx *ctx, enum note_level level, const char *key,
    const char *a, const char *b, int err)
{
	struct note *n;

	if (ctx->note_count == ctx->note_cap) {
		ctx->note_cap = ctx->note_cap ? ctx->note_cap * 2 : 16;
		ctx->notes = xrealloc(ctx->notes,
		    ctx->note_cap * sizeof *ctx->notes);
	}
	n = &ctx->notes[ctx->note_count++];
	n->level = level;
	n->key = key;
	n->a = dup_or_null(a);
	n->b = dup_or_null(b);
	n->err = err;
	if (level != NOTE_INFO)
		ctx->failed = 1;
	DEBUG_LOG("note %s %s a=%s b=%s errno=%d (%s)", level == NOTE_ERROR ?
	    "ERROR" : level == NOTE_WARNING ? "WARNING" : "info", key,
	    a != NULL ? a : "-", b != NULL ? b : "-", err,
	    err != 0 ? strerror(err) : "-");
}

void move_note(struct move_ctx *ctx, enum note_level level, const char *key,
    const char *a, const char *b, int err)
{
	note(ctx, level, key, a, b, err);
}

void move_init(struct move_ctx *ctx, int apply)
{
	struct claude_paths paths;

	memset(ctx, 0, sizeof *ctx);
	ctx->apply = apply;
	claude_paths_init(&paths);
	ctx->home = paths.home;
	ctx->config_dir = paths.config_dir;
	ctx->projects_dir = paths.projects_dir;
	ctx->config_file = paths.config_file;
	ctx->data_dir = platform_data_dir(ctx->home);
	DEBUG_LOG("run %s: config_dir=%s projects_dir=%s config_file=%s",
	    apply ? "APPLY" : "plan", ctx->config_dir, ctx->projects_dir,
	    ctx->config_file);
}

/* Forgets the notes and the plan; the run (and its .bak) goes on. */
void move_clear(struct move_ctx *ctx)
{
	size_t i;

	for (i = 0; i < ctx->note_count; i++) {
		free(ctx->notes[i].a);
		free(ctx->notes[i].b);
	}
	ctx->note_count = 0;
	change_list_free(&ctx->plan);
}

void move_free(struct move_ctx *ctx)
{
	move_clear(ctx);
	free(ctx->notes);
	free(ctx->home);
	free(ctx->config_dir);
	free(ctx->projects_dir);
	free(ctx->config_file);
	free(ctx->data_dir);
	ctx->notes = NULL;
	ctx->note_cap = 0;
}

static int compare_names(const void *a, const void *b)
{
	return strcmp(*(char *const *)a, *(char *const *)b);
}

/* The sorted entry names of dir; NULL with errno when it cannot be read. */
static char **list_dir(const char *dir, size_t *count)
{
	struct dirent *e;
	char **names;
	size_t n = 0, cap = 16;
	DIR *d;

	*count = 0;
	d = opendir(dir);
	if (d == NULL)
		return NULL;
	names = xmalloc(cap * sizeof *names);
	while ((e = readdir(d)) != NULL) {
		if (strcmp(e->d_name, ".") == 0 || strcmp(e->d_name, "..") == 0)
			continue;
		if (n == cap) {
			cap *= 2;
			names = xrealloc(names, cap * sizeof *names);
		}
		names[n++] = xstrdup(e->d_name);
	}
	closedir(d);
	qsort(names, n, sizeof *names, compare_names);
	*count = n;
	return names;
}

static void free_names(char **names, size_t count)
{
	size_t i;

	for (i = 0; i < count; i++)
		free(names[i]);
	free(names);
}

static int has_suffix(const char *s, const char *suffix)
{
	size_t n, m;

	n = strlen(s);
	m = strlen(suffix);
	return n >= m && strcmp(s + n - m, suffix) == 0;
}

/*
 * rename(2), and the system mv across file systems: mv carries extended
 * attributes, ACLs and the other metadata a copy of our own would lose.
 */
int move_tree(const char *from, const char *to)
{
	char *argv[5];
	pid_t pid;
	int status, r;

	if (rename(from, to) == 0) {
		DEBUG_LOG("rename %s -> %s: ok", from, to);
		return 0;
	}
	DEBUG_LOG("rename %s -> %s: %s", from, to, strerror(errno));
	if (errno != EXDEV)
		return -1;
	argv[0] = (char *)"mv";
	argv[1] = (char *)"--";
	argv[2] = (char *)from;
	argv[3] = (char *)to;
	argv[4] = NULL;
	r = posix_spawn(&pid, PLATFORM_MV, NULL, NULL, argv, environ);
	if (r != 0) {
		errno = r;
		return -1;
	}
	while (waitpid(pid, &status, 0) < 0)
		if (errno != EINTR)
			return -1;
	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		DEBUG_LOG("%s %s -> %s: failed, wait status %d", PLATFORM_MV,
		    from, to, status);
		errno = EIO;
		return -1;
	}
	DEBUG_LOG("%s %s -> %s: ok", PLATFORM_MV, from, to);
	return 0;
}

/* 1 when Claude Code runs, 0 when not, -1 with errno when unknown. */
int claude_running(void)
{
	const char *name;
	int r;

	name = getenv("CSM_CLAUDE_PROCESS");
	if (name == NULL || name[0] == '\0')
		name = CLAUDE_PROCESS;
	r = platform_process_running(name);
	DEBUG_LOG("process \"%s\" running: %d%s%s", name, r, r < 0 ? " " : "",
	    r < 0 ? strerror(errno) : "");
	return r;
}

/* Borrows the strings. The script pairs the paths the same way. */
static void set_pairs(struct pairs *ps, const char *old_logical,
    const char *new_logical, const char *old_physical,
    const char *new_physical)
{
	DEBUG_LOG("paths logical %s -> %s, physical %s -> %s", old_logical,
	    new_logical, old_physical, new_physical);
	ps->p[0].old_path = old_logical;
	ps->p[0].new_path = new_logical;
	ps->count = 1;
	if (strcmp(old_physical, old_logical) != 0 ||
	    strcmp(new_physical, new_logical) != 0) {
		ps->p[1].old_path = old_physical;
		ps->p[1].new_path = new_physical;
		ps->count = 2;
	}
}

static void push_change(struct change_list *list, const struct change *c)
{
	if (list->count == list->cap) {
		list->cap = list->cap ? list->cap * 2 : 16;
		list->items = xrealloc(list->items,
		    list->cap * sizeof *list->items);
	}
	list->items[list->count++] = *c;
}

/*
 * Plans or makes the changes of one file. The changes join the plan; a
 * projects key that stays because the new one exists becomes a warning.
 */
static void rewrite_one(struct move_ctx *ctx, const char *file,
    enum rewrite_kind kind, const struct rewrite_rules *rules)
{
	struct change_list plan, conflicts;
	size_t i;
	int status, err;

	memset(&plan, 0, sizeof plan);
	memset(&conflicts, 0, sizeof conflicts);
	status = rewrite_file(file, kind, rules, &plan, ctx->apply,
	    &ctx->backup_done);
	err = errno;
	DEBUG_LOG("rewrite %s (%s): status %d, %zu changes%s%s", file,
	    kind == REWRITE_CONFIG ? "config" : kind == REWRITE_INDEX ?
	    "index" : "session", status, plan.count,
	    status == REWRITE_ERROR ? ", " : "",
	    status == REWRITE_ERROR ? strerror(err) : "");
	for (i = 0; i < plan.count; i++)
		DEBUG_LOG("  change kind %d line %zu %s: %s -> %s",
		    (int)plan.items[i].kind, plan.items[i].line,
		    plan.items[i].field != NULL ? plan.items[i].field : "-",
		    plan.items[i].old_value != NULL ? plan.items[i].old_value :
		    "-", plan.items[i].new_value != NULL ?
		    plan.items[i].new_value : "-");
	if (kind == REWRITE_CONFIG && plan.count > 0)
		note(ctx, NOTE_INFO, "move.config", file, NULL, 0);
	if (status == REWRITE_ERROR)
		note(ctx, NOTE_ERROR, "error.file", file, NULL, err);
	else if (status == REWRITE_INVALID)
		note(ctx, NOTE_WARNING, "warn.invalid", file, NULL, 0);
	for (i = 0; i < plan.count; i++) {
		if (plan.items[i].kind == CHANGE_CONFLICT) {
			note(ctx, NOTE_WARNING, "warn.key",
			    plan.items[i].old_value, plan.items[i].new_value, 0);
			push_change(&conflicts, &plan.items[i]);
		} else {
			push_change(&ctx->plan, &plan.items[i]);
		}
	}
	free(plan.items);
	change_list_free(&conflicts);
}

/* The session files below path; a symlink is never followed. */
static void rewrite_tree(struct move_ctx *ctx, const char *path,
    const struct rewrite_rules *rules)
{
	struct stat st;
	char **names, *child, *base;
	size_t count, i;

	if (lstat(path, &st) != 0) {
		note(ctx, NOTE_ERROR, "error.read", path, NULL, errno);
		return;
	}
	if (S_ISDIR(st.st_mode)) {
		names = list_dir(path, &count);
		if (names == NULL) {
			note(ctx, NOTE_ERROR, "error.read", path, NULL, errno);
			return;
		}
		for (i = 0; i < count; i++) {
			child = xjoin(path, names[i]);
			rewrite_tree(ctx, child, rules);
			free(child);
		}
		free_names(names, count);
		return;
	}
	if (!S_ISREG(st.st_mode))
		return;
	base = path_base(path);
	if (has_suffix(base, ".jsonl"))
		rewrite_one(ctx, path, REWRITE_SESSION, rules);
	else if (strcmp(base, "sessions-index.json") == 0)
		rewrite_one(ctx, path, REWRITE_INDEX, rules);
	free(base);
}

/* Takes ownership of from and to. */
static void add_move(struct moves *m, char *from, char *to)
{
	if (m->count == m->cap) {
		m->cap = m->cap ? m->cap * 2 : 16;
		m->items = xrealloc(m->items, m->cap * sizeof *m->items);
	}
	m->items[m->count].from = from;
	m->items[m->count].to = to;
	m->count++;
}

static void add_dir(struct moves *m, const char *dir)
{
	if (m->dir_count == m->dir_cap) {
		m->dir_cap = m->dir_cap ? m->dir_cap * 2 : 16;
		m->dirs = xrealloc(m->dirs, m->dir_cap * sizeof *m->dirs);
	}
	m->dirs[m->dir_count++] = xstrdup(dir);
}

static void free_moves(struct moves *m)
{
	size_t i;

	for (i = 0; i < m->count; i++) {
		free(m->items[i].from);
		free(m->items[i].to);
	}
	for (i = 0; i < m->dir_count; i++)
		free(m->dirs[i]);
	free(m->items);
	free(m->dirs);
}

/*
 * What merging from into the existing directory to does: an entry missing
 * in to moves whole, a directory on both sides is merged in turn, anything
 * else on both sides is never overwritten: it stays in from and is
 * reported. Symlinks are entries like files, never followed.
 */
static void plan_merge(struct move_ctx *ctx, const char *from, const char *to,
    const char *kept, struct moves *m)
{
	struct stat fs, ts;
	char **names, *f, *t;
	size_t count, i;

	names = list_dir(from, &count);
	if (names == NULL) {
		note(ctx, NOTE_ERROR, "error.read", from, NULL, errno);
		return;
	}
	add_dir(m, from);
	for (i = 0; i < count; i++) {
		f = xjoin(from, names[i]);
		t = xjoin(to, names[i]);
		if (lstat(t, &ts) != 0) {
			if (errno == ENOENT) {
				add_move(m, f, t);
				continue;
			}
			note(ctx, NOTE_ERROR, "error.read", t, NULL, errno);
		} else if (S_ISDIR(ts.st_mode) && lstat(f, &fs) == 0 &&
		    S_ISDIR(fs.st_mode)) {
			plan_merge(ctx, f, t, kept, m);
		} else {
			note(ctx, NOTE_WARNING, kept, f, to, 0);
		}
		free(f);
		free(t);
	}
	free_names(names, count);
}

/*
 * Makes the moves (with apply) and rewrites the moved files when rules is
 * not NULL; without apply the plan of the rewrite comes from the files
 * where they are now. The emptied directories go, deepest first; one with
 * something left behind stays.
 */
static void apply_moves(struct move_ctx *ctx, struct moves *m,
    const char *kept, const struct rewrite_rules *rules)
{
	struct stat st;
	char *dir;
	size_t i;

	for (i = 0; i < m->count; i++) {
		if (ctx->apply) {
			/* rename(2) replaces a file, so look right before it. */
			if (lstat(m->items[i].to, &st) == 0) {
				DEBUG_LOG("kept %s: %s exists", m->items[i].from,
				    m->items[i].to);
				dir = path_dir(m->items[i].to);
				note(ctx, NOTE_WARNING, kept, m->items[i].from,
				    dir, 0);
				free(dir);
				continue;
			}
			if (move_tree(m->items[i].from, m->items[i].to) != 0) {
				note(ctx, NOTE_ERROR, "error.move",
				    m->items[i].from, NULL, errno);
				continue;
			}
		}
		if (rules != NULL)
			rewrite_tree(ctx, ctx->apply ? m->items[i].to :
			    m->items[i].from, rules);
	}
	if (ctx->apply)
		for (i = m->dir_count; i > 0; i--) {
			if (rmdir(m->dirs[i - 1]) == 0)
				DEBUG_LOG("rmdir %s: ok", m->dirs[i - 1]);
			else
				DEBUG_LOG("rmdir %s: %s", m->dirs[i - 1],
				    strerror(errno));
		}
}

/*
 * Moves the directory from to to, merging it into to when that exists,
 * as with session directories (4.3); nothing is rewritten. A file on both
 * sides stays in from and is noted under the key kept. 1 when merged.
 */
int move_merge(struct move_ctx *ctx, const char *from, const char *to,
    const char *kept)
{
	struct moves m;
	struct stat st;
	int merged;

	memset(&m, 0, sizeof m);
	merged = lstat(to, &st) == 0;
	if (merged)
		plan_merge(ctx, from, to, kept, &m);
	else
		add_move(&m, xstrdup(from), xstrdup(to));
	apply_moves(ctx, &m, kept, NULL);
	free_moves(&m);
	return merged;
}

/*
 * Moves one session directory to the name of its new project path: a
 * rename, or a merge when a directory of that name exists. Then the moved
 * files get the new paths. Without apply only the plan is made, from the
 * files where they are now.
 */
static void move_session_dir(struct move_ctx *ctx, const struct pairs *ps,
    const struct session_dir *sd)
{
	struct rewrite_rules rules;
	struct moves m;
	struct stat st;
	char *new_name, *new_dir;
	int merged = 0;

	memset(&m, 0, sizeof m);
	new_name = path_encode(sd->new_cwd);
	new_dir = xjoin(ctx->projects_dir, new_name);
	rules.projects = ps->p;
	rules.project_count = ps->count;
	rules.old_session_dir = sd->path;
	rules.new_session_dir = new_dir;
	DEBUG_LOG("session dir %s -> %s (new cwd %s)", sd->name, new_name,
	    sd->new_cwd);
	if (strcmp(new_name, sd->name) == 0) {
		/* Both paths encode to one name (my.repo, my-repo). */
		note(ctx, NOTE_INFO, "move.sessions", sd->name, new_name, 0);
		rules.old_session_dir = rules.new_session_dir = NULL;
		rewrite_tree(ctx, sd->path, &rules);
		goto done;
	}
	if (lstat(new_dir, &st) == 0) {
		if (!S_ISDIR(st.st_mode)) {
			note(ctx, NOTE_ERROR, "error.session.target", new_dir,
			    NULL, 0);
			goto done;
		}
		merged = 1;
	} else if (errno != ENOENT) {
		note(ctx, NOTE_ERROR, "error.read", new_dir, NULL, errno);
		goto done;
	}
	note(ctx, NOTE_INFO, merged ? "move.sessions.merge" : "move.sessions",
	    sd->name, new_name, 0);
	if (merged)
		plan_merge(ctx, sd->path, new_dir, "warn.kept", &m);
	else
		add_move(&m, xstrdup(sd->path), xstrdup(new_dir));
	apply_moves(ctx, &m, "warn.kept", &rules);
done:
	free_moves(&m);
	free(new_name);
	free(new_dir);
}

/*
 * A session directory without any cwd (only memory/, say) belongs to the
 * project whose path encodes to its name. Only the project itself: the
 * lossy name cannot tell which subdirectory it was.
 */
static char *cwd_from_name(const char *name, const struct pairs *ps)
{
	char *encoded;
	size_t i;
	int same;

	for (i = 0; i < ps->count; i++) {
		encoded = path_encode(ps->p[i].old_path);
		same = strcmp(encoded, name) == 0;
		free(encoded);
		if (same)
			return xstrdup(ps->p[i].old_path);
	}
	return NULL;
}

/*
 * Every session directory of the project or below it moves. The list is
 * made first, as the moves change the directory being read.
 */
static void move_sessions(struct move_ctx *ctx, const struct pairs *ps)
{
	struct session_dir *dirs = NULL;
	struct stat st;
	char **names, *path, *cwd, *new_cwd;
	size_t count, i, n = 0;

	names = list_dir(ctx->projects_dir, &count);
	if (names == NULL) {
		if (errno != ENOENT)
			note(ctx, NOTE_ERROR, "error.read", ctx->projects_dir,
			    NULL, errno);
		return;
	}
	dirs = xmalloc((count + 1) * sizeof *dirs);
	for (i = 0; i < count; i++) {
		path = xjoin(ctx->projects_dir, names[i]);
		if (lstat(path, &st) != 0 || !S_ISDIR(st.st_mode)) {
			free(path);
			continue;
		}
		cwd = session_dir_cwd(path);
		DEBUG_LOG("scan %s: cwd %s", names[i], cwd != NULL ? cwd :
		    "(none)");
		if (cwd == NULL) {
			cwd = cwd_from_name(names[i], ps);
			if (cwd != NULL)
				DEBUG_LOG("  matched by name: %s", cwd);
		}
		new_cwd = cwd != NULL ?
		    rewrite_project_path(ps->p, ps->count, cwd) : NULL;
		if (new_cwd != NULL)
			DEBUG_LOG("  belongs to the project, new cwd %s",
			    new_cwd);
		free(cwd);
		if (new_cwd == NULL) {
			free(path);
			continue;
		}
		dirs[n].name = xstrdup(names[i]);
		dirs[n].path = path;
		dirs[n].new_cwd = new_cwd;
		n++;
	}
	free_names(names, count);
	for (i = 0; i < n; i++) {
		move_session_dir(ctx, ps, &dirs[i]);
		free(dirs[i].name);
		free(dirs[i].path);
		free(dirs[i].new_cwd);
	}
	free(dirs);
}

static void move_config(struct move_ctx *ctx, const struct pairs *ps)
{
	struct rewrite_rules rules;

	rules.projects = ps->p;
	rules.project_count = ps->count;
	rules.old_session_dir = rules.new_session_dir = NULL;
	rewrite_one(ctx, ctx->config_file, REWRITE_CONFIG, &rules);
}

/*
 * Moves a repository like mv (into target when it is a directory) and its
 * session directories with it. The physical paths move; the sessions and
 * .claude.json follow both variants. Nothing about the sessions changes
 * until the move is confirmed. 0 on success, -1 when something failed.
 */
int move_repo(struct move_ctx *ctx, const char *source, const char *target)
{
	struct pairs ps;
	struct stat st;
	char *src_l, *src_p, *dst_l = NULL, *dst_p = NULL, *t_l, *t_p, *base;
	char *parent_l = NULL, *parent_p = NULL;
	int failed = ctx->failed;

	ctx->failed = 0;
	DEBUG_LOG("move source=%s target=%s", source, target);
	src_l = path_logical(source);
	src_p = path_physical(source);
	if (src_l == NULL || src_p == NULL) {
		note(ctx, NOTE_ERROR, "error.path", source, NULL, errno);
		goto done;
	}
	if (stat(src_p, &st) != 0 || !S_ISDIR(st.st_mode)) {
		note(ctx, NOTE_ERROR, "error.not_dir", src_l, NULL, 0);
		goto done;
	}
	t_l = path_logical(target);
	t_p = path_physical(target);
	if (t_l == NULL || t_p == NULL) {
		note(ctx, NOTE_ERROR, "error.path", target, NULL, errno);
		free(t_l);
		free(t_p);
		goto done;
	}
	if (stat(t_p, &st) == 0 && S_ISDIR(st.st_mode)) {
		base = path_base(src_l);
		dst_l = xjoin(t_l, base);
		dst_p = xjoin(t_p, base);
		free(base);
		free(t_l);
		free(t_p);
	} else {
		dst_l = t_l;
		dst_p = t_p;
	}
	DEBUG_LOG("move logical %s -> %s, physical %s -> %s", src_l, dst_l,
	    src_p, dst_p);
	parent_l = path_dir(dst_l);
	parent_p = path_dir(dst_p);
	if (lstat(dst_p, &st) == 0)
		note(ctx, NOTE_ERROR, "error.exists", dst_l, NULL, 0);
	else if (stat(parent_p, &st) != 0 || !S_ISDIR(st.st_mode))
		note(ctx, NOTE_ERROR, "error.not_dir", parent_l, NULL, 0);
	else if (path_has_prefix(dst_p, src_p))
		note(ctx, NOTE_ERROR, "error.inside", src_l, NULL, 0);
	if (ctx->failed)
		goto done;
	note(ctx, NOTE_INFO, "move.repo", src_l, dst_l, 0);
	if (ctx->apply) {
		if (move_tree(src_p, dst_p) != 0) {
			note(ctx, NOTE_ERROR, "error.move", src_l, NULL, errno);
			goto done;
		}
		if (stat(dst_p, &st) != 0 || !S_ISDIR(st.st_mode) ||
		    lstat(src_p, &st) == 0 || errno != ENOENT) {
			note(ctx, NOTE_ERROR, "error.unconfirmed", src_l, NULL,
			    0);
			goto done;
		}
	}
	set_pairs(&ps, src_l, dst_l, src_p, dst_p);
	move_sessions(ctx, &ps);
	move_config(ctx, &ps);
done:
	free(src_l);
	free(src_p);
	free(dst_l);
	free(dst_p);
	free(parent_l);
	free(parent_p);
	failed |= ctx->failed;
	ctx->failed = failed;
	return ctx->failed ? -1 : 0;
}

/* Whether path may exist: anything but a clear "no such file". */
static int may_exist(const char *path)
{
	struct stat st;

	return lstat(path, &st) == 0 || (errno != ENOENT && errno != ENOTDIR);
}

/*
 * Moves the sessions of a repository already moved by hand. The old path
 * must be gone in both variants, or the repository has not moved.
 */
int move_fix(struct move_ctx *ctx, const char *old_path, const char *new_path)
{
	struct pairs ps;
	struct stat st;
	char *old_l, *old_p, *new_l = NULL, *new_p = NULL;
	int failed = ctx->failed;

	ctx->failed = 0;
	DEBUG_LOG("fix old=%s new=%s", old_path, new_path);
	old_l = path_logical(old_path);
	old_p = path_physical(old_path);
	if (old_l == NULL || old_p == NULL) {
		note(ctx, NOTE_ERROR, "error.path", old_path, NULL, errno);
		goto done;
	}
	new_l = path_logical(new_path);
	new_p = path_physical(new_path);
	if (new_l == NULL || new_p == NULL) {
		note(ctx, NOTE_ERROR, "error.path", new_path, NULL, errno);
		goto done;
	}
	if (may_exist(old_l) || may_exist(old_p)) {
		note(ctx, NOTE_ERROR, "error.fix.exists", old_l, NULL, 0);
		goto done;
	}
	if (stat(new_p, &st) != 0 || !S_ISDIR(st.st_mode)) {
		note(ctx, NOTE_ERROR, "error.fix.missing", new_l, NULL, 0);
		goto done;
	}
	note(ctx, NOTE_INFO, "fix.repo", old_l, new_l, 0);
	set_pairs(&ps, old_l, new_l, old_p, new_p);
	move_sessions(ctx, &ps);
	move_config(ctx, &ps);
done:
	free(old_l);
	free(old_p);
	free(new_l);
	free(new_p);
	failed |= ctx->failed;
	ctx->failed = failed;
	return ctx->failed ? -1 : 0;
}
